struct Sum {value:f64,correction:f64}
impl Sum {fn add(&mut self,x:f64)->Result<()>{if !x.is_finite() || x<0.0{return Err("nonnegative finite loss".into());}let y=x-self.correction;let t=self.value+y;self.correction=(t-self.value)-y;self.value=t;if !t.is_finite(){return Err("loss total finite".into());}Ok(())}}
