    let mut node_json=String::new();node_json.try_reserve_exact(20000).map_err(|_|"node report allocation")?;node_json.push('[');for c in 0..2{if c!=0{node_json.push(',');}node_json.push('[');for node in 0..142{if node!=0{node_json.push(',');}let a=nodes[c][node];write!(&mut node_json,"[{},{},{},{:.12},{:.12}]",a.branches,a.coded,teacher.diagnostic_class(c,node)?,a.static_q.value,a.teacher_q.value).map_err(|_|"node report formatting")?;}node_json.push(']');}node_json.push(']');if node_json.len()>20000 || node_json.capacity()>32768{return Err("node report 20KiB bound".into());}
